        if r['timeseries_id'] in ids:
            data[r['timeseries_id']][r['timestamp']]=float(r['value'])

def hour(ts): return int(ts[11:13])

def period_mean(tsid, start, end, hstart=8, hend=18):
    vals=[v for t,v in data[tsid].items() if start<=t<end and hstart<=hour(t)<hend]
    if not vals: return None, 0
    return sum(vals)/len(vals), len(vals)

before=('2018-05-01','2018-06-15')
after=('2018-06-15','2019-01-01')

def report(name, key):
    print(f"\n=== {name} ===")
    for z,v in zones.items():
        csp,esp,t=v
        tsid={0:csp,1:esp,2:t}[key]
        if tsid is None:
            print(f"{z}: (no {name[:3]})")
            continue
        m1,n1=period_mean(tsid,*before)
        m2,n2=period_mean(tsid,*after)
        d=(m2-m1) if (m1 is not None and m2 is not None) else None
        print(f"{z}: before={None if m1 is None else round(m1,2)} n={n1} | after={None if m2 is None else round(m2,2)} n={n2} | delta={None if d is None else round(d,2)}")

report("Zone temperature",2)
report("Cooling setpoint",0)
